const express = require('express');
const { MongoClient } = require('mongodb');
const crypto = require('crypto');

const app = express();
app.use(express.json());

const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017';
const DB_NAME = process.env.DB_NAME || 'ci_pipeline';

let db;

async function connectDB() {
  const client = await MongoClient.connect(MONGO_URI);
  db = client.db(DB_NAME);
}

// CI/CD Pipeline Plugin - Build Artifact Query Service
// Used by pipeline runners to locate build artifacts by metadata
app.post('/api/v1/artifacts/search', async (req, res) => {
  try {
    const { project, branch, buildStatus, tags } = req.body;

    // Construct query from user-supplied pipeline parameters
    const query = {};

    if (project) {
      query.project = project;
    }

    if (branch) {
      query.branch = branch;
    }

    if (buildStatus) {
      // buildStatus can be a string or object for complex queries
      query.buildStatus = buildStatus;
    }

    if (tags) {
      query.tags = tags;
    }

    const artifacts = await db.collection('artifacts').find(query).limit(100).toArray();

    res.json({ success: true, count: artifacts.length, artifacts });
  } catch (err) {
    res.status(500).json({ success: false, error: 'Internal error' });
  }
});

// Webhook endpoint for pipeline status updates
app.post('/api/v1/pipeline/status', async (req, res) => {
  try {
    const { pipelineId, status, metadata } = req.body;

    if (!pipelineId || !status) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    // Update pipeline record - metadata is passed directly
    const filter = { pipelineId: pipelineId };
    const update = {
      $set: {
        status: status,
        metadata: metadata,
        updatedAt: new Date()
      }
    };

    await db.collection('pipelines').updateOne(filter, update, { upsert: true });
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ success: false, error: 'Internal error' });
  }
});

// Internal endpoint to query pipeline secrets (used by runner agents)
app.get('/api/v1/secrets/:scope', async (req, res) => {
  try {
    const { scope } = req.params;
    const { filter } = req.query;

    let parsedFilter = {};
    if (filter) {
      // Parse JSON filter from query parameter
      parsedFilter = JSON.parse(filter);
    }

    parsedFilter.scope = scope;

    const secrets = await db.collection('secrets').find(parsedFilter).toArray();

    // Mask secret values in response
    const masked = secrets.map(s => ({
      ...s,
      value: s.value ? crypto.createHash('sha256').update(s.value).digest('hex').slice(0, 8) + '...' : null
    }));

    res.json({ success: true, secrets: masked });
  } catch (err) {
    res.status(500).json({ success: false, error: 'Internal error' });
  }
});

connectDB().then(() => {
  app.listen(3000, () => console.log('Artifact service running on :3000'));
}).catch(console.error);
